1	package net.officefloor.hq.app.invoices;
2	
3	import java.math.BigDecimal;
4	import java.time.LocalDate;
5	import java.util.List;
6	import net.officefloor.hq.app.Audit;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.jdbc.core.RowMapper;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	/**
13	 * Business logic for invoices. Invoices are always viewed in the context of their project, so the
14	 * list is scoped by project id. The derived total the UI shows is computed by the front-end from the
15	 * returned rows; this service just surfaces the project's invoices in a stable order. Marking an
16	 * invoice paid flips its status and records an audit entry so the action can be checked later.
17	 */
18	@Service
19	public class InvoiceService {
20	
21	    private final InvoiceRepository repository;
22	    private final JdbcTemplate jdbc;
23	    private final Audit audit;
24	
25	    public InvoiceService(InvoiceRepository repository, JdbcTemplate jdbc, Audit audit) {
26	        this.repository = repository;
27	        this.jdbc = jdbc;
28	        this.audit = audit;
29	    }
30	
31	    /** Every invoice across all projects; narrowed to a single lifecycle stage when {@code status} is given. */
32	    @Transactional(readOnly = true)
33	    public List<AllInvoiceView> listAll(String status) {
34	        RowMapper<AllInvoiceView> mapper = (rs, i) -> new AllInvoiceView(rs.getLong("id"),
35	                rs.getString("project_name"), rs.getBigDecimal("amount"), rs.getString("status"));
36	        String base = "SELECT i.id, i.amount, i.status, p.name AS project_name "
37	                + "FROM invoices i JOIN projects p ON i.project_id = p.id ";
38	        if (status == null || status.isBlank()) {
39	            return jdbc.query(base + "ORDER BY i.id ASC", mapper);
40	        }
41	        return jdbc.query(base + "WHERE i.status = ? ORDER BY i.id ASC", mapper, status.trim());
42	    }
43	
44	    @Transactional(readOnly = true)
45	    public List<InvoiceView> listForProject(Long projectId) {
46	        return jdbc.query(
47	                "SELECT id, project_id, amount, status, issued_date, due_date FROM invoices WHERE project_id = ? ORDER BY id ASC",
48	                (rs, i) -> new InvoiceView(rs.getLong("id"), rs.getLong("project_id"),
49	                        rs.getBigDecimal("amount"), rs.getString("status"),
50	                        rs.getDate("issued_date").toLocalDate().toString(),
51	                        rs.getDate("due_date").toLocalDate().toString()),
