    if (res.ok) {
      setTasks(await res.json());
    }
  }

  useEffect(() => {
    void load();
    void loadTasks();
  }, [projectId]);

  // Tick a task off (or back on): toggles OPEN <-> DONE and reloads the list.
  async function onToggleTask(taskId: number) {
    const res = await fetch(`/api/tasks/${taskId}/toggle`, { method: 'POST' });
    if (res.ok) {
      await loadTasks();
    }
  }

