    const value = Number(amount);
    if (!(value > 0)) {
      setAmountError(true);
      return;
    }
    setAmountError(false);
    const res = await fetch(`/api/projects/${projectId}/invoices`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ amount: Number(amount) }),
    });
    if (res.ok) {
      setAmount('');
      await load();
    }
  }

